SELECT S.[ID], S.[LABEL], S.[TRIGGER], S.[CREATED_DATE], P.[KEY] AS PROJECT_KEY 
FROM [PROJECT_SCHEMA_SNAPSHOTS] S 
	INNER JOIN [PROJECTS] P 
			ON S.[PROJECT_ID] = P.[ID] 
WHERE P.[KEY] = @PRM_PROJECTS_KEY 
